def strategy(history, rng):
    if not history:
        return 'C'
    n = len(history)
    my = [h[0] for h in history]
    op = [h[1] for h in history]
    opD = op.count('D')
    opC = n - opD
    myD = my.count('D')
    myC = n - myD

    if n >= 2:
        if my[-1] == 'D' and op[-1] == 'D' and my[-2] == 'D' and op[-2] == 'D':
            return 'C'

    if n < 4:
        if opD == 0:
            return 'C'
        if opD == n:
            return 'D'
        return 'C'

    last_me = my[-1]
    last_op = op[-1]

    # Detect pure cooperator: exploit near the end, otherwise cooperate
    if opD == 0:
        if n >= 96:
            return 'D'
        return 'C'

    # Detect pure defector: defect
    if opC == 0:
        if n >= 2 and my[-1] == 'D' and my[-2] == 'D' and n % 5 == 0:
            return 'C'
        return 'D'

    # Endgame: defect in last few rounds
    if n >= 97:
        return 'D'

    # Immediate retaliation but with occasional forgiveness
    if last_op == 'D':
        # Check recent opponent defection density
        look = 6 if n >= 6 else n
        recent_opD = 0
        for i in range(n - look, n):
            if op[i] == 'D':
                recent_opD += 1
        if recent_opD >= 3:
            return 'D'
        # Single recent defection: retaliate but forgive sometimes
        if rng.random() < 0.15:
            return 'C'
        return 'D'

    # Opponent just cooperated
    # Check if opponent has high overall defection rate - be wary
    if opD * 3 >= n * 2:
        # Mostly defective overall; defect preemptively sometimes
        if rng.random() < 0.6:
            return 'D'
        return 'C'

    # If we just defected and opponent cooperated, we might be exploiting - 
    # but avoid over-exploiting a generally cooperative opponent
    if last_me == 'D':
        if opD * 4 <= n:
            # Opponent quite cooperative; continue cooperating to maintain
            return 'C'
        if rng.random() < 0.4:
            return 'D'
        return 'C'

    # Opponent has been quite cooperative overall - cooperate
    if opD * 5 <= n:
        return 'C'

    # Moderate defection rate: tit-for-tat bias toward cooperation
    if n >= 8:
        recent_opD = 0
        look = 8
        for i in range(n - look, n):
            if op[i] == 'D':
                recent_opD += 1
        if recent_opD >= 3:
            return 'D'
        if recent_opD <= 1:
            return 'C'

    return 'C'
